-- Vantara Logística — incidente de 12/05/2026 (dados de 04/05 a 13/05 06:00).
-- Gerado por tools/gen-case-005.ts. Não edite à mão: rode o gerador de novo.
-- Cada fonte grava com o próprio relógio.

CREATE TABLE employees (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  department TEXT NOT NULL,
  job_title TEXT NOT NULL,
  badge_id INTEGER NOT NULL UNIQUE,
  shift TEXT NOT NULL,
  username TEXT NOT NULL UNIQUE
);

CREATE TABLE absences (
  id INTEGER PRIMARY KEY,
  employee_id INTEGER NOT NULL REFERENCES employees(id),
  kind TEXT NOT NULL,
  start_date TEXT NOT NULL,
  end_date TEXT NOT NULL
);

CREATE TABLE assets (
  asset_tag TEXT PRIMARY KEY,
  type TEXT NOT NULL,
  model TEXT NOT NULL,
  serial_number TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL,
  location TEXT NOT NULL,
  assigned_to INTEGER REFERENCES employees(id)
);

CREATE TABLE badge_events (
  id INTEGER PRIMARY KEY,
  badge_id INTEGER NOT NULL,
  gate TEXT NOT NULL,
  direction TEXT NOT NULL,
  event_time TEXT NOT NULL
);

CREATE TABLE timesheet (
  id INTEGER PRIMARY KEY,
  employee_id INTEGER NOT NULL REFERENCES employees(id),
  work_date TEXT NOT NULL,
  clock_in TEXT NOT NULL,
  clock_out TEXT NOT NULL
);

CREATE TABLE ad_logons (
  id INTEGER PRIMARY KEY,
  username TEXT NOT NULL,
  host TEXT NOT NULL,
  logon_type TEXT NOT NULL,
  src_host TEXT NOT NULL,
  event_time TEXT NOT NULL
);

CREATE TABLE vpn_sessions (
  id INTEGER PRIMARY KEY,
  username TEXT NOT NULL,
  src_ip TEXT NOT NULL,
  started_at TEXT NOT NULL,
  ended_at TEXT NOT NULL
);

CREATE TABLE dhcp_leases (
  id INTEGER PRIMARY KEY,
  ip TEXT NOT NULL,
  host TEXT NOT NULL,
  lease_start TEXT NOT NULL,
  lease_end TEXT NOT NULL
);

CREATE TABLE fw_events (
  id INTEGER PRIMARY KEY,
  src_ip TEXT NOT NULL,
  dst_ip TEXT NOT NULL,
  dst_scope TEXT NOT NULL,
  bytes_out INTEGER NOT NULL,
  event_time TEXT NOT NULL
);

CREATE TABLE edr_events (
  id INTEGER PRIMARY KEY,
  host TEXT NOT NULL,
  user TEXT NOT NULL,
  process TEXT NOT NULL,
  event_time TEXT NOT NULL
);

CREATE TABLE heartbeats (
  source TEXT NOT NULL,
  seq INTEGER NOT NULL,
  event_time TEXT NOT NULL,
  PRIMARY KEY (source, seq)
);

